# Define function to pull top 10 by report
top_10_movies &lt;- function(df, period) {
  # code block
  result &lt;- df |&gt; 
    filter(report == period) |&gt; 
    slice_max(order_by = views, n = 10) |&gt; 
    select(title, views)
  return(result)
}

